+
+    content.replace(ipRegex, "10.0.0.1");
+    content.replace(macRegex, "02:00:00:00:00:01");
+
+    file.seek(0);
+    file.resize(0);
+    QTextStream out(&file);
+    out << content;
+    file.close();
